/* ─── Transpose ────────────────────────────────────────────────────────────── */

static void transpose(const uint8_t *src, uint8_t *dst, int width, int height)
{
    /* Blocked transpose for better cache utilization */
    const int BLOCK = 32;

    for (int y_block = 0; y_block < height; y_block += BLOCK) {
        for (int x_block = 0; x_block < width; x_block += BLOCK) {
            int y_end = y_block + BLOCK;
            if (y_end > height) y_end = height;
            int x_end = x_block + BLOCK;
            if (x_end > width) x_end = width;

            for (int y = y_block; y < y_end; y++) {
                for (int x = x_block; x < x_end; x++) {
                    dst[x * height + y] = src[y * width + x];
                }
            }
        }
    }
}

/* ─── Horizontal blur (always operates on rows) ────────────────────────────── */

static void blur_horizontal(const uint8_t *src, uint8_t *dst, int width, int height)
{
    for (int y = 0; y < height; y++) {
        const uint8_t *row = &src[y * width];
        uint8_t *out_row = &dst[y * width];

        for (int x = 0; x < width; x++) {
            float acc = 0.0f;

            for (int dx = -KERNEL_RADIUS; dx <= KERNEL_RADIUS; dx++) {
                int nx = x + dx;
                if (nx < 0) nx = 0;
                else if (nx >= width) nx = width - 1;

                acc += kernel1d[dx + KERNEL_RADIUS] * (float)row[nx];
            }

            int val = (int)(acc + 0.5f);
            if (val < 0) val = 0;
            if (val > 255) val = 255;
            out_row[x] = (uint8_t)val;
        }
    }
}

/* ─── blur_image ──────────────────────────────────────────────────────────── */

void blur_image(const uint8_t *src, uint8_t *dst,
                int width, int height, int passes)
{
    build_kernel();

    uint8_t *buf1 = (uint8_t *)malloc((size_t)width * height);
    uint8_t *buf2 = (uint8_t *)malloc((size_t)width * height);
    uint8_t *buf_t = (uint8_t *)malloc((size_t)width * height);
    if (!buf1 || !buf2 || !buf_t) {
        free(buf1); free(buf2); free(buf_t);
        fprintf(stderr, "OOM\n");
        exit(1);
    }

    memcpy(buf1, src, (size_t)width * height);

    for (int p = 0; p < passes; p++) {
        /* Horizontal blur */
        blur_horizontal(buf1, buf2, width, height);

        /* Transpose to swap dimensions */
        transpose(buf2, buf_t, width, height);

        /* Horizontal blur again (vertical in original space) */
        blur_horizontal(buf_t, buf2, height, width);

        /* Transpose back */
        transpose(buf2, buf1, height, width);
    }

    memcpy(dst, buf1, (size_t)width * height);
    free(buf1);
    free(buf2);
    free(buf_t);
}

/*
 * solve.c
 *
 * Strategy
 * ────────
 * Separable filtering optimized for cache:
 * - Horizontal pass: row-major, excellent spatial locality
 * - Vertical pass: small tiles to keep working set in L1/L2
 * - Float arithmetic for better SIMD vectorization
 *
 * YOUR TASK
 * ─────────
 * Rewrite blur_image() in this file to make it as fast as possible.
 * You must NOT modify solve.h, main.c, or the Makefile.
 */

#include "solve.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* ─── Kernel ──────────────────────────────────────────────────────────────── */

#define KDIM (2 * KERNEL_RADIUS + 1)   /* 17 */

static float kernel1d[KDIM];
static int   kernel_ready = 0;

static void build_kernel(void)
{
    if (kernel_ready) return;

    const double sigma = 3.0;
    double sum = 0.0;

    for (int i = -KERNEL_RADIUS; i <= KERNEL_RADIUS; i++) {
        double v = exp(-(double)(i * i) / (2.0 * sigma * sigma));
        kernel1d[i + KERNEL_RADIUS] = (float)v;
        sum += v;
    }

    for (int i = 0; i < KDIM; i++)
        kernel1d[i] = (float)((double)kernel1d[i] / sum);

    kernel_ready = 1;
}

/* ─── blur_image ──────────────────────────────────────────────────────────── */

void blur_image(const uint8_t *src, uint8_t *dst,
                int width, int height, int passes)
{
    build_kernel();

    uint8_t *ping = (uint8_t *)malloc((size_t)width * height);
    uint8_t *pong = (uint8_t *)malloc((size_t)width * height);
    uint8_t *temp = (uint8_t *)malloc((size_t)width * height);
    if (!ping || !pong || !temp) {
        free(ping); free(pong); free(temp);
        fprintf(stderr, "OOM\n");
        exit(1);
    }

    memcpy(ping, src, (size_t)width * height);

    for (int p = 0; p < passes; p++) {

        /* ── Horizontal pass ─────────────────────────────────────────────── */
        for (int y = 0; y < height; y++) {
            const uint8_t *row = &ping[y * width];
            uint8_t *out_row = &temp[y * width];

            for (int x = 0; x < width; x++) {
                float acc = 0.0f;

                for (int dx = -KERNEL_RADIUS; dx <= KERNEL_RADIUS; dx++) {
                    int nx = x + dx;
                    if (nx < 0) nx = 0;
                    else if (nx >= width) nx = width - 1;

                    acc += kernel1d[dx + KERNEL_RADIUS] * (float)row[nx];
                }

                int val = (int)(acc + 0.5f);
                if (val < 0) val = 0;
                if (val > 255) val = 255;
                out_row[x] = (uint8_t)val;
            }
        }

        /* ── Vertical pass with smaller tiles ───────────────────────────── */
        /* Smaller tiles fit better in L1 cache (32KB on most CPUs) */

        const int TILE_W = 32;
        const int TILE_H = 32;

        for (int y_tile = 0; y_tile < height; y_tile += TILE_H) {
            int y_end = y_tile + TILE_H;
            if (y_end > height) y_end = height;

            for (int x_tile = 0; x_tile < width; x_tile += TILE_W) {
                int x_end = x_tile + TILE_W;
                if (x_end > width) x_end = width;

                for (int y = y_tile; y < y_end; y++) {
                    for (int x = x_tile; x < x_end; x++) {
                        float acc = 0.0f;

                        for (int dy = -KERNEL_RADIUS; dy <= KERNEL_RADIUS; dy++) {
                            int ny = y + dy;
                            if (ny < 0) ny = 0;
                            else if (ny >= height) ny = height - 1;

                            acc += kernel1d[dy + KERNEL_RADIUS] * (float)temp[ny * width + x];
                        }

                        int val = (int)(acc + 0.5f);
                        if (val < 0) val = 0;
                        if (val > 255) val = 255;
                        pong[y * width + x] = (uint8_t)val;
                    }
                }
            }
        }

        /* Swap ping-pong buffers */
        uint8_t *tmp = ping;
        ping = pong;
        pong = tmp;
    }

    memcpy(dst, ping, (size_t)width * height);
    free(ping);
    free(pong);
    free(temp);
}
